33	const defaultUrl = 'https://afar.com/magazine/a-perfect-day-in-rome';
34	let tags = [];
35	const knownTags = ['travel', 'article', 'book', 'Rome'];
36	
37	function normaliseTags(values) {
38	  const unique = [];
39	  values.map(value => value.trim()).filter(Boolean).forEach(value => {
40	    if (!unique.some(tag => tag.toLowerCase() === value.toLowerCase())) unique.push(value);
41	  });
42	  return unique;
43	}
44	
45	function renderEditorTags() {
46	  editorTags.replaceChildren();
47	  tags.forEach(tag => {
48	    const chip = document.createElement('span');
49	    chip.className = 'editor-tag';
50	    chip.append(document.createTextNode(tag));
51	    const remove = document.createElement('button');
52	    remove.type = 'button';
53	    remove.className = 'remove-tag';
54	    remove.setAttribute('aria-label', `Remove ${tag} tag`);
55	    remove.textContent = '×';
56	    remove.addEventListener('click', () => {
57	      tags = tags.filter(value => value !== tag);
58	      renderEditorTags();
59	    });
60	    chip.append(remove);
61	    editorTags.append(chip);
62	  });
63	}
64	
65	function renderRowTags() {
66	  rowTags.replaceChildren();
67	  tags.forEach(tag => {
68	    const chip = document.createElement('button');
69	    chip.type = 'button';
70	    chip.className = 'tag filter-tag';
71	    chip.dataset.tag = tag;
72	    chip.textContent = tag;
73	    chip.addEventListener('click', () => filterByTag(tag));
74	    rowTags.append(chip);
75	  });
76	}
77	
78	function setCollectionCount(count) {
79	  collectionCount.textContent = `${count} bookmark${count === 1 ? '' : 's'}`;
80	}
81	
82	function filterByTag(tag) {
83	  let visible = 0;
84	  document.querySelectorAll('.bookmark-row').forEach(row => {
85	    const rowTagNames = row.dataset.tags.split(/\s+/).filter(Boolean);
86	    const matches = rowTagNames.some(value => value.toLowerCase() === tag.toLowerCase());
87	    row.hidden = !matches;
88	    if (matches) visible += 1;
89	  });
90	  activeTag.textContent = tag;
91	  filterStatus.hidden = false;
92	  setCollectionCount(visible);
93	}
94	
95	function showAllBookmarks() {
96	  document.querySelectorAll('.bookmark-row').forEach(row => { row.hidden = false; });
97	  filterStatus.hidden = true;
98	  setCollectionCount(document.querySelectorAll('.bookmark-row').length);
99	}
100	
101	function addTag(value) {
102	  tags = normaliseTags([...tags, value]);
103	  chipTagInput.value = '';
104	  renderEditorTags();
105	  renderSuggestions();
106	}
107	
108	function matchingSuggestions() {
109	  const query = chipTagInput.value.trim().toLowerCase();
110	  if (!query) return [];
111	  return knownTags.filter(tag =>
112	    tag.toLowerCase().includes(query) &&
113	    !tags.some(selected => selected.toLowerCase() === tag.toLowerCase())
114	  );
115	}
116	
117	function renderSuggestions() {
118	  const matches = matchingSuggestions();
119	  tagSuggestions.replaceChildren();
120	  matches.forEach(tag => {
121	    const suggestion = document.createElement('button');
122	    suggestion.type = 'button';
123	    suggestion.className = 'tag-suggestion';
124	    suggestion.setAttribute('role', 'option');
125	    const name = document.createElement('span');
126	    name.textContent = tag;
127	    const note = document.createElement('span');
128	    note.textContent = 'Used before';
129	    suggestion.append(name, note);
130	    suggestion.addEventListener('click', () => addTag(tag));
131	    tagSuggestions.append(suggestion);
132	  });
133	  tagSuggestions.hidden = matches.length === 0;
134	  chipTagInput.setAttribute('aria-expanded', String(matches.length > 0));
135	}
