138	  captureView.hidden = view !== captureView;
139	  libraryView.hidden = view !== libraryView;
140	  detailView.hidden = view !== detailView;
141	  window.scrollTo({ top: 0, behavior: 'smooth' });
142	}
143	
144	function showToast(message) {
145	  toast.textContent = message;
146	  toast.classList.add('show');
147	  window.setTimeout(() => toast.classList.remove('show'), 1800);
148	}
