151	  savedUrl.value = savedUrl.value || defaultUrl;
152	  titleInput.value = rowTitle.textContent;
153	  descriptionInput.value = rowDescription.textContent;
154	  renderEditorTags();
155	  commaTagInput.value = tags.join(', ');
156	  document.querySelector('.saved-banner').hidden = true;
157	  showView(detailView);
158	  titleInput.focus();
159	}
160	
